private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    // If both arguments are null, consider it a match
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null and the other is not, no match
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLength = suffix.length();
    // Empty suffix matches everything
    if (suffixLength == 0) {
        return true;
    }
    // String shorter than suffix cannot match
    if (str.length() < suffixLength) {
        return false;
    }
    if (ignoreCase) {
        // Compare the ending substring case‑insensitively
        String endOfStr = str.substring(str.length() - suffixLength);
        return endOfStr.equalsIgnoreCase(suffix);
    } else {
        // Case‑sensitive comparison
        return str.endsWith(suffix);
    }
}

