public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null");
    }
    // Add all vertices to the graph
    for (V v : resultMap.values()) {
        target.addVertex(v);
    }
    // Build a list of vertices
    java.util.List<V> vertexList = new java.util.ArrayList<>(resultMap.values());
    int n = vertexList.size();
    if (n < 2) {
        return; // no bipartite edges to add
    }
    int mid = n / 2;
    java.util.List<V> left = vertexList.subList(0, mid);
    java.util.List<V> right = vertexList.subList(mid, n);
    // Connect every vertex in left to every vertex in right
    for (V u : left) {
        for (V v : right) {
            target.addEdge(u, v);
        }
    }
}

@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap must not be null");
    }
    // Add all vertices from the result map to the graph (idempotent)
    for (V v : resultMap.values()) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }
    // Build bipartition: split the vertices into two groups (first half vs. second half)
    List<V> vertices = new ArrayList<>(resultMap.values());
    int total = vertices.size();
    if (total < 2) {
        // Not enough vertices for a bipartite graph
        return;
    }
    int split = total / 2; // first split vertices as group A
    // Add edges between every vertex in group A and every vertex in group B
    for (int i = 0; i < split; i++) {
        V u = vertices.get(i);
        for (int j = split; j < total; j++) {
            V v = vertices.get(j);
            if (!target.containsEdge(u, v)) {
                target.addEdge(u, v);
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("target and resultMap must not be null");
    }
    // To create a complete bipartite graph we split the vertices into two sets.
    // Here we use the key length parity as a simple deterministic split.
    java.util.List<V> left = new java.util.ArrayList<>();
    java.util.List<V> right = new java.util.ArrayList<>();

    // Add all vertices and segregate them
    for (java.util.Map.Entry<String, V> entry : resultMap.entrySet()){
        V vertex = entry.getValue();
        if (vertex == null) continue; // ignore null vertices
        target.addVertex(vertex);
        if (entry.getKey() != null && entry.getKey().length() % 2 == 0){
            left.add(vertex);
        } else {
            right.add(vertex);
        }
    }

    // Now add edges between every pair of vertices from different partitions.
    for (V vLeft : left){
        for (V vRight : right){
            // If the graph doesn't allow parallel edges or self-loops,
            // the addEdge method will handle it appropriate to the implementation.
            target.addEdge(vLeft, vRight);
        }
